entries[469989] = { ["name"] = "Gehärteter Gewitterpelz", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nGelegentlich sind Pelze von algarischen Kreaturen besonders robust. Dadurch sind sie in traditionellem Handwerk nur schwierig zu verarbeiten, aber wenn Ihr sie studiert, können sie Euch zu Durchbrüchen bei Eurem Kürschnereiwissen verhelfen.\n\nIhr könnt diese Woche fünf weitere(n) gehärtete(n) Pelz(e) finden.\nBeruf:\nKürschnerei (1)" }
entries[469991] = { ["name"] = "Zeichen der Verdammnis", ["text"] = "30 Meter Reichweite\nSofort 30 sek. Abklingzeit\n1 Aufladung\nPlatziert ein Zeichen der Flamme am Zielort, das sich nach 2 Sek. aktiviert.\n\nFügt allen vom Zeichen betroffenen Gegnern sofort (53.2827% der Angriffskraft) Feuer schaden sowie im Verlauf von 8 Sek. zusätzlich (133.385% der Angriffskraft) Feuer schaden zu.\n\nErzeugt 30 Jähzorn." }
