entries[470032] = { ["name"] = "Kolossaler Zusammenstoß", ["text"] = "Unbegrenzte Reichweite\nSofort\nBei Erreichen von 100 Energie treffen Leuchtendo und Torq für 20 Sek. in der Mitte der Arena aufeinander. Ihr Kampf fügt allen Spielercharakteren alle 1 Sek. 251553 Feuer- und 251553 Naturschaden zu und lässt ' Schockblitz e' und ' Feurige Welle n' aus ihnen hervorbrechen.\n\nJeder Zusammenstoß erhöht den Schaden von ' Kolossaler Zusammenstoß ' um 30%. Dieser Effekt ist stapelbar." }
