entries[470053] = { ["name"] = "Voltaiklohe", ["text"] = "Ca. 5.75 Procs pro Minute\n'Blitzschlag' und 'Kettenblitzschlag' haben eine hohe Chance, Euren nächsten 'Flammenschock' zu 'Voltaiklohe' zu machen.\n\nVoltaiklohe\nSchockt das Ziel sowie 5 Gegner in der Nähe sofort mit glühendem Donner, verursacht (400% der Zaubermacht) Naturschaden und wendet 'Flammenschock' an.\n\nErzeugt 1 Stapel von 'Waffe des Mahlstroms'.\n(1s Abklingzeit)" }
