entries[470055] = { ["name"] = "S.A.D.", ["text"] = "Sofort\nFügt einem Gegenstand der Saison 2 von War Within, der noch keinen Sockel besitzt, einen hinzu. Kann auf Helme, Armschienen oder Gürtel angewandt werden. Kann nicht für PvP-Ausrüstung verwendet werden." }
entries[470056] = { ["name"] = "Schockblitz", ["text"] = "Unbegrenzte Reichweite\nSofort\nEin künstlicher Blitz schlägt ein und fügt Spielercharakteren innerhalb von 5 Metern um den Einschlag 40 Naturschaden zu." }
entries[470057] = { ["name"] = "Voltaiklohe", ["text"] = "40 Meter Reichweite\nSofort\nSchockt das Ziel sowie 5 Gegner in der Nähe sofort mit glühendem Donner, verursacht (400% der Zaubermacht) Naturschaden und wendet 'Flammenschock' an.\n\nErzeugt 1 Stapel von 'Waffe des Mahlstroms'." }
entries[470058] = { ["name"] = "Voltaiklohe", ["text"] = "Sofort\n'Blitzschlag' und 'Kettenblitzschlag' haben eine hohe Chance, Euren nächsten 'Flammenschock' zu 'Voltaiklohe' zu machen.\n\nVoltaiklohe\nSchockt das Ziel sowie 5 Gegner in der Nähe sofort mit glühendem Donner, verursacht (400% der Zaubermacht) Naturschaden und wendet 'Flammenschock' an.\n\nErzeugt 1 Stapel von 'Waffe des Mahlstroms'." }
entries[470059] = { ["name"] = "Arkane Überladung", ["text"] = "Kanalisiert (Wirken in 1 Stunde)\nArkanotron wirft eine Arkanbombe auf eine Position in der Nähe. Wenn die Bombe auf dem Boden aufkommt, explodiert sie und fügt allen Spielercharakteren 1755 Arkanschaden zu.\n\nWenn die Bombe einen Spielercharakter trifft, fügt sie ihm 585 Arkanschaden zu und erhöht seinen erlittenen Arkanschaden 40 Sek. lang um 10%. Arkanotron wirft eine weitere Bombe, die schneller auf dem Boden aufkommt.\n\n'Arkane Überladung' fügt dem Schlachtzug pro Bombe, die gefangen wurde, weniger Schaden zu." }
entries[470061] = { ["name"] = "Statische Aufladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nTorqs Anzug verstärkt die elektrischen Ladungen, die innerhalb von 70 Metern generiert werden. Bis zum nächsten Einsatz von ' Kolossaler Zusammenstoß ' durchströmt eine elektrische Ladung die Spielercharaktere in Reichweite und verursacht alle 1 Sek. 117391 Naturschaden. Außerdem steigt die Ladung, während sich das Ziel innerhalb der Reichweite bewegt und fällt, solange es stillsteht. Bei maximaler Ladung bricht es als ' Statische Entladung ' aus." }
entries[470062] = { ["name"] = "Verstärken", ["text"] = "Wirken in 1 sek.\nLässt den Zaubernden 12 Sek. lang 30% weniger Schaden erleiden und heilt ihn alle 5.2 Sek. um 1 Gesundheit." }
