entries[470167] = { ["name"] = "Volle Ladung", ["text"] = "Sofort\nErlangt die Fähigkeit, während des Meereszornunwetters auf der Sireneninsel den TR-06 Verprügler und den N.U.K.U.L.A.R.-Zielmarkierer zu aktivieren." }
entries[470168] = { ["name"] = "Cyrces Zephir", ["text"] = "Sofort\nWährend Ihr Cyrces Reif angelegt habt und Euch auf der Sireneninsel befindet, haben Eure Zauber und Fähigkeiten eine Chance, Cyrces Zephir zu beschwören, der im Verlauf von 3 Sek. alle vorhandenen Fähigkeiten des singenden Citrins einsetzt." }
entries[470169] = { ["name"] = "Diebe der Sirene", ["text"] = "Sofort\nCyrces Reif markiert jetzt passiv unsichtbare Gegner, die versuchen, die Reichtümer der Sireneninsel zu stehlen. Sie lassen sich oft dabei überraschen, wie sie versuchen, flammengesegnetes Eisen von den stärksten Kreaturen der Insel zu stehlen." }
entries[470170] = { ["name"] = "Schwingen der Sirene", ["text"] = "Sofort\nCyrces Reif ermöglicht Euch jetzt passiv, die Winde zu beherrschen, sodass Ihr über der Sireneninsel fliegen könnt." }
