entries[470194] = { ["name"] = "Eisstoß", ["text"] = "0.66% von Grundmana Nahkampfreichweite\nSofort 15 sek. Abklingzeit\nTrifft Euer Ziel mit einer eisigen Klinge, fügt ihm (285.66% der Angriffskraft) Frostschaden zu und verringert seine Bewegungsgeschwindigkeit 6 Sek. lang um 50%.\n\n'Eisstoß' erhöht den Schaden Eures nächsten Einsatzes von 'Frostschock' um 100% und erzeugt 1 Stapel von 'Waffe des Mahlstroms'." }
entries[470197] = { ["name"] = "Segen des Meeresbewohners", ["text"] = "Sofort\nErlangt in den Gewässern um die Sireneninsel die passive Fähigkeit, auf dem Meeresboden zu wandeln, Schätze unter Wasser zu finden und unter Wasser zu atmen sowie deutlich schneller zu schwimmen.\n\nIhr müsst Cyrces Reif angelegt haben." }
entries[470200] = { ["name"] = "Feuerflöhe", ["text"] = "Nahkampfreichweite\nSofort 2 min Abklingzeit\nTempo um 25% verringert.\nChance von 10%, bei erlittenem Treffer Flöhe auf Verbündete überspringen zu lassen.\n(Procchance: 10%)" }
entries[470203] = { ["name"] = "Einäschern", ["text"] = "100 Energie 200 Meter Reichweite\nWirken in 3 sek.\nBotschafter Flammenschlag kanalisiert seinen vollen Zorn auf sein Ziel und fügt Spielercharakteren innerhalb von 10 Metern alle 1 Sek. 7022 Feuerschaden zu, die unter allen getroffenen Gegner aufgeteilt werden.\n\nBotschafter Flammenschlags Energie wird wiederaufgefüllt, wenn sein Ziel stirbt.\n\nBotschafter Flammenschlags Ziel wird mit ' Flammenschlag ' belegt." }
entries[470207] = { ["name"] = "Flammenschlag", ["text"] = "200 Meter Reichweite\nSofort\nLässt einen Spielercharakter 1.3 Min. lang 50% mehr Feuerschaden erleiden." }
